import React from "react";
// import background from '../../assets/image/cut.png'
import { useState, useEffect } from "react";
import CryptoJS from "crypto-js";
import { Link, useNavigate } from "react-router-dom";
import { Spinner, Alert } from "flowbite-react";
import { signInStart, signInSuccess, signInFailure } from "../../redux/user/userSlice";
import { useDispatch, useSelector } from "react-redux";
import { Phone, Eye, EyeOff } from "lucide-react";


// Load environment variables from .env file
import { SECRET_KEY } from '../../config/env.tsx';
const background = require("../../assets/image/cut.png");




interface RootState {
  user: {
    currentUser: null | any;
    access_token: string | null;
    refresh_token: string | null;
    loading: boolean;
    error: string | null;
  }
}
export default function Login() {
  const [formData, setFormData] = useState({
      email_phone: "",
      password: "",
  
  });
  const [showPassword, setShowPassword] = useState(false); // State cho xem/ẩn password
  const [rememberMe, setRememberMe] = useState(false); // State cho remember me
  const dispatch = useDispatch();
  const { loading, error: errorMessage } = useSelector((state: RootState) => state.user);
  const navigate = useNavigate();
  
  // Load dữ liệu từ localStorage khi trang khởi tạo
  useEffect(() => {
    const savedEmail = localStorage.getItem("savedEmail");
    const savedPasswordEncrypted = localStorage.getItem("savedPassword");
    if (savedEmail && savedPasswordEncrypted) {
      try {
        // Kiểm tra xem savedPassword có phải là chuỗi mã hóa không
        const bytes = CryptoJS.AES.decrypt(savedPasswordEncrypted, SECRET_KEY);
        const decryptedPassword = bytes.toString(CryptoJS.enc.Utf8);
        if (decryptedPassword) {
          setFormData({
            email_phone: savedEmail,
            password: decryptedPassword,
          });
          setRememberMe(true);
        } else {
          // Nếu không giải mã được, xóa dữ liệu cũ
          console.log("Invalid encrypted password, clearing localStorage");
          localStorage.removeItem("savedEmail");
          localStorage.removeItem("savedPassword");
        }
      } catch (error) {
        console.error("Failed to decrypt password:", error);
        localStorage.removeItem("savedEmail");
        localStorage.removeItem("savedPassword");
      }
    }
  }, []);

  const handleChange  = (e) => {
    setFormData({...formData, [e.target.id]: e.target.value.trim()});

  }
  const toggleShowPassword = () => {
    setShowPassword((prev) => !prev);
  };
  // Hàm lưu tokens vào localStorage
  const storeTokens = (access_token, refresh_token, email) => {
    localStorage.setItem("access_token", access_token);
    localStorage.setItem("refresh_token", refresh_token);
    localStorage.setItem("userEmail", email);
    if (rememberMe) {
      console.log("Saving to localStorage with rememberMe:", formData);
      if (!formData.email_phone || !formData.password) {
        console.error("Email or password is empty, cannot save to localStorage");
        return;
      }
      localStorage.setItem("savedEmail", formData.email_phone);
      const encryptedPassword = CryptoJS.AES.encrypt(formData.password, SECRET_KEY).toString();
      console.log("Encrypted password:", encryptedPassword); // Debug
      localStorage.setItem("savedPassword", encryptedPassword);
    } else {
      localStorage.removeItem("savedEmail");
      localStorage.removeItem("savedPassword");
    }
  };
// Hàm refresh token
const refresh_token = async () => {
  try {
      const refresh_token = localStorage.getItem('refresh_token');
      // const res = await fetch("http://localhost:8001/api/auth/refresh-token", {
      //     method: "POST",
      //     headers: {
      //         "Content-Type": "application/json",
      //     },
      //     body: JSON.stringify({ refreshToken }),
      // });
      // const res = await fetch("http://localhost:8000/api/users/refresh-token", {
      const res = await fetch("http://localhost:8000/api/users/refresh-token", {  
      method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({ refresh_token }),

    });

      const data = await res.json();
      if (res.status === 201 && data.success) {
          storeTokens(data.access_token, data.refresh_token, data.data.email);
          dispatch(signInSuccess({
              user: data.data,
              access_token: data.access_token,
              refresh_token: data.refresh_token
          }));
          return data.access_token;
      } else {
          throw new Error("Refresh token failed");
      }
  } catch (error) {
      dispatch(signInFailure("Session expired. Please login again."));
      navigate("/login");
      throw error;
  }
};

const handleSubmit = async (e) => {
  e.preventDefault();
  console.log("1. Form submitted:", formData);

  if (!formData.email_phone || !formData.password) {
    console.log("2. Missing fields, dispatching failure");
    return dispatch(signInFailure("All fields are required!"));
  }

  try {
    console.log("3. Starting sign-in process");
    dispatch(signInStart());
    const requestBody = { email: formData.email_phone, password: formData.password };
    console.log("4. Request body:", requestBody);

    const res = await fetch("http://localhost:8000/api/users/signin", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(requestBody),
    });
    console.log("5. Fetch completed, status:", res.status);

    const data = await res.json();
    console.log("6. Response data:", data);

    if ((res.status === 200 || res.status === 201) && data.success) {
      console.log("7. Sign-in successful");
      const email = data.data.email;
      storeTokens(data.access_token, data.refresh_token, email);
      dispatch(signInSuccess({ 
        user: data.data, 
        access_token: data.access_token, 
        refresh_token: data.refresh_token 
      }));
      navigate("/home");
    } else {
      console.log("8. Sign-in failed with message:", data.message);
      dispatch(signInFailure(data.message || "Login failed"));
    }
  } catch (error) {
    console.log("9. Error caught:", error.message);
    dispatch(signInFailure(error.message || "Something went wrong"));
  } finally {
    // Đảm bảo loading luôn được tắt nếu cần
    // dispatch(signInFailure(null)); // Có thể cần thêm logic để reset loading
  }
};
  // console.log(formData);
  return (
    <div className="font-[sans-serif]">
      <div className="flex flex-col items-center justify-center w-full h-screen">
        <div className="grid md:grid-cols-2  gap-4 max-md:gap-8 max-w-full w-full h-full m-0 rounded-md flex-col items-center justify-center">
          <div className="flex flex-col items-center justify-center">
            <div className="m-3 md:max-w-md w-full flex flex-col items-center justify-center">
                <form className="w-full max-w-sm" onSubmit={handleSubmit}>
                  <div className="mb-12 flex flex-col items-center justify-center">
                    <h3 className="text-gray-800 text-4xl font-bold">Welcome back!</h3>
                    <p className="text-sm mt-4 text-gray-800">Don't have an account 
                      <Link to="/register" className="text-blue-600 font-semibold hover:underline ml-1 whitespace-nowrap">Register here</Link>
                    </p>
                  </div>

                  <div>
                    {/* <label className="text-gray-800 text-xs block mb-2">Email</label>
                    <div className="relative flex items-center">
                      <input name="email" type="text" id="email"  required onChange={handleChange} className="w-full text-gray-800 text-sm border-b border-gray-300 focus:border-blue-600 px-2 py-3 outline-none" placeholder="name@gmail.com" />
                      <svg xmlns="http://www.w3.org/2000/svg" fill="#bbb" stroke="#bbb" className="w-[18px] h-[18px] absolute right-2" viewBox="0 0 682.667 682.667">
                        <defs>
                          <clipPath id="a" clipPathUnits="userSpaceOnUse">
                            <path d="M0 512h512V0H0Z" data-original="#000000"></path>
                          </clipPath>
                        </defs>
                        <g clip-path="url(#a)" transform="matrix(1.33 0 0 -1.33 0 682.667)">
                          <path fill="none" stroke-miterlimit="10" stroke-width="40" d="M452 444H60c-22.091 0-40-17.909-40-40v-39.446l212.127-157.782c14.17-10.54 33.576-10.54 47.746 0L492 364.554V404c0 22.091-17.909 40-40 40Z" data-original="#000000"></path>
                          <path d="M472 274.9V107.999c0-11.027-8.972-20-20-20H60c-11.028 0-20 8.973-20 20V274.9L0 304.652V107.999c0-33.084 26.916-60 60-60h392c33.084 0 60 26.916 60 60v196.653Z" data-original="#000000"></path>
                        </g>
                      </svg>
                    </div> */}
                    <label className="text-gray-800 text-xs block mb-2">Email hoặc Phone</label>
                    <div className="relative flex items-center">
                      <input 
                          name="email_phone" 
                          type="text" 
                          id="email_phone"  
                          required 
                          onChange={handleChange} 
                          value={formData.email_phone}
                          className="w-full text-gray-800 text-sm border-b border-gray-300 focus:border-blue-600 px-2 py-3 outline-none" 
                          placeholder="Nhập email hoặc Phone" />
                    </div>
                  </div>

                  <div className="mt-8">
                    <label className="text-gray-800 text-xs block mb-2">Password</label>
                    <div className="relative flex items-center">
                      <input name="password" type={showPassword ? "text" : "password"} id="password" required onChange={handleChange} value={formData.password} className="w-full text-gray-800 text-sm border-b border-gray-300 focus:border-blue-600 px-2 py-3 outline-none" placeholder="Enter password" />
                      <button
                      type="button"
                      onClick={toggleShowPassword}
                      className="absolute right-2 cursor-pointer"
                    >
                      {showPassword ? (
                        <EyeOff className="w-[18px] h-[18px] text-gray-500" />
                      ) : (
                        <Eye className="w-[18px] h-[18px] text-gray-500" />
                      )}
                    </button>
                    </div>
                  </div>
                  <div className="flex items-center mt-6">
                  <input
                    id="remember-me"
                    name="remember-me"
                    type="checkbox"
                    checked={rememberMe}
                    onChange={(e) => setRememberMe(e.target.checked)}
                    className="h-4 w-4 shrink-0 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
                  />
                  <label htmlFor="remember-me" className="ml-3 block text-sm text-gray-800">
                    Remember me
                  </label>
                </div>
                  

                  <div className="mt-8">
                    {/* <Link to="/home"> */}
                    <button 
  type="submit" 
  disabled={loading}
  className="w-full shadow-xl py-1 px-4 text-sm tracking-wide rounded-md text-white bg-green-700 hover:bg-green-800 focus:outline-none"
>
  {loading ? (
    <>
      <Spinner size="sm" />
      <span className="pl-3">Loading...</span>
    </>
  ) : (
    "Login"
  )}
</button>
                    {/* </Link> */}
                    {errorMessage && (<Alert className="mt5 text-red-500" >{errorMessage}</Alert>)} 
                  </div>
                         
                  <div className="flex items-center justify-center mt-9 mb-9">
                    <div className="flex-grow border-t border-gray-300"></div>
                    <span className="mx-4 text-black-500">Or</span>
                    <div className="flex-grow border-t border-gray-300"></div>
                  </div>

                  
                </form>
                
                <div className="max-w-sm mx-auto mt-6 border rounded-lg shadow-lg p-0.5 bg-white cursor-pointer hover:bg-gray-100">
                    <div className="space-x-4 flex justify-center">
                      <div className="flex items-center ml-5">
                          <button type="button" className="border-none outline-none">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20px" className="inline" viewBox="0 0 512 512">
                              <path fill="#fbbd00" d="M120 256c0-25.367 6.989-49.13 19.131-69.477v-86.308H52.823C18.568 144.703 0 198.922 0 256s18.568 111.297 52.823 155.785h86.308v-86.308C126.989 305.13 120 281.367 120 256z" data-original="#fbbd00" />
                              <path fill="#0f9d58" d="m256 392-60 60 60 60c57.079 0 111.297-18.568 155.785-52.823v-86.216h-86.216C305.044 385.147 281.181 392 256 392z" data-original="#0f9d58" />
                              <path fill="#31aa52" d="m139.131 325.477-86.308 86.308a260.085 260.085 0 0 0 22.158 25.235C123.333 485.371 187.62 512 256 512V392c-49.624 0-93.117-26.72-116.869-66.523z" data-original="#31aa52" />
                              <path fill="#3c79e6" d="M512 256a258.24 258.24 0 0 0-4.192-46.377l-2.251-12.299H256v120h121.452a135.385 135.385 0 0 1-51.884 55.638l86.216 86.216a260.085 260.085 0 0 0 25.235-22.158C485.371 388.667 512 324.38 512 256z" data-original="#3c79e6" />
                              <path fill="#cf2d48" d="m352.167 159.833 10.606 10.606 84.853-84.852-10.606-10.606C388.668 26.629 324.381 0 256 0l-60 60 60 60c36.326 0 70.479 14.146 96.167 39.833z" data-original="#cf2d48" />
                              <path fill="#eb4132" d="M256 120V0C187.62 0 123.333 26.629 74.98 74.98a259.849 259.849 0 0 0-22.158 25.235l86.308 86.308C162.883 146.72 206.376 120 256 120z" data-original="#eb4132" />
                            </svg>
                          </button>
                        </div>
                        <div>
                          <p className="text-base mt-1">
                          Sign in with Google
                          </p>
                        </div>
                      </div>
                    </div>     
            </div>
          </div>

          <div className="md:h-full rounded-xl relative bg-cover bg-center" style={{ backgroundImage: `url(${background})` }}>
            <div className="absolute inset-0 bg-black opacity-20 rounded-xl"></div>
          </div>
        </div>
      </div>
    </div>
  );
}